mapper.select:
WITH eligible AS (
    SELECT s.started_at,
           GREATEST(extract(epoch FROM (s.ended_at - s.started_at)), 0) AS duration_seconds,
           r.avg_viewers,
           COALESCE(r.total_chat, 0) AS total_chat
      FROM broadcast_sessions s
      JOIN reports r ON r.session_id = s.id
     WHERE s.streamer_id = #{streamerId}
       AND s.status = 'ENDED'
       AND r.status IN ('COMPLETED', 'PARTIAL')
       AND s.started_at >= #{previousStart}
       AND s.started_at < #{currentEnd}
),
aggregate AS (
    SELECT count(*) FILTER (
               WHERE started_at >= #{currentStart} AND started_at < #{currentEnd}
           ) > 0 AS has_current_data,
           COALESCE(round(
               sum(avg_viewers * duration_seconds) FILTER (
                   WHERE started_at >= #{currentStart} AND started_at < #{currentEnd}
                     AND avg_viewers IS NOT NULL
               )
               / NULLIF(sum(duration_seconds) FILTER (
                   WHERE started_at >= #{currentStart} AND started_at < #{currentEnd}
                     AND avg_viewers IS NOT NULL
               ), 0)
           ), 0)::int AS current_avg_viewers,
           COALESCE(sum(total_chat) FILTER (
               WHERE started_at >= #{currentStart} AND started_at < #{currentEnd}
           ), 0)::bigint AS current_total_chat,
           COALESCE(round(
               sum(avg_viewers * duration_seconds) FILTER (
                   WHERE started_at >= #{previousStart} AND started_at < #{currentStart}
                     AND avg_viewers IS NOT NULL
               )
               / NULLIF(sum(duration_seconds) FILTER (
                   WHERE started_at >= #{previousStart} AND started_at < #{currentStart}
                     AND avg_viewers IS NOT NULL
               ), 0)
           ), 0)::int AS previous_avg_viewers,
           COALESCE(sum(total_chat) FILTER (
               WHERE started_at >= #{previousStart} AND started_at < #{currentStart}
           ), 0)::bigint AS previous_total_chat
      FROM eligible
)
SELECT has_current_data, current_avg_viewers, current_total_chat,
       previous_avg_viewers, previous_total_chat
  FROM aggregate
